/* 02 thinking */
.think-head{display:flex;align-items:center;gap:14px;width:100%;padding:14px 16px;text-align:left}
.think-head .t{font-weight:600;font-size:15px}
.think-head .chev{margin-left:auto;color:var(--muted);transition:transform .5s var(--ease)}
.think-head[aria-expanded="false"] .chev{transform:rotate(-90deg)}
.trace-box{border-top:1px solid var(--line);padding:6px 0;transition:border-color .4s ease}
.unfold:not(.open)>.uf>.trace-box{border-top-color:transparent}
.trace-item{display:flex;gap:12px;align-items:flex-start;padding:9px 16px;font-size:14px;color:var(--text-dim);transition:color .35s ease}
.trace-item .st{width:16px;height:16px;flex:none;margin-top:2px;display:grid;place-items:center}
.trace-item.done{color:var(--text)}
.trace-item.done .st{color:var(--success)}
.spin{width:10px;height:10px;border:1.5px solid var(--accent);border-top-color:transparent;border-radius:50%;animation:spin .9s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.trace-item .sub{display:block;font-family:var(--mono);font-size:11px;color:var(--muted);text-transform:uppercase;margin-top:2px}
.trace-item code{font-family:var(--mono);font-size:12px;color:var(--text)}
.reason{padding:4px 16px 4px;font-size:14px;line-height:1.6;color:var(--text-dim);border-left:2px solid var(--line);margin:8px 16px}

/* word reveal for streamed text */
.w{opacity:0;filter:blur(4px);transition:opacity .5s ease,filter .5s ease}
.w.in{opacity:1;filter:blur(0)}

/* reasoning trail: a connecting line that grows with each step */
.trail>div{position:relative}
.trail>div:not(:last-child) .trace-item::after{content:"";position:absolute;left:23.5px;top:30px;bottom:-11px;width:1px;background:var(--line);transition:background-color .4s ease}
.trail>div:not(:last-child) .trace-item.done::after{background:rgba(62,207,142,.45)}
.trail .trace-item{position:relative}
.trail .trace-item .st{position:relative;z-index:1;background:var(--panel);box-shadow:0 0 0 3px var(--panel)}

/* ---------- 02 thinking ---------- */
const thHead = $('#th-head'), thFold = $('#th-fold'), thTrace = $('#th-trace'), thTitle = $('#th-title'), thTime = $('#th-time'), thIcon = $('#th-icon');
const thinkData = {
  steps: { icon:'stars', items:[
    ['Opened the onboarding file','4 frames'],
    ['Compared it against the design system','12 components'],
    ['Found spacing that breaks the 8px grid','3 frames'],
    ['Drafted fixes for review','Ready']
  ]},
  reasoning: { icon:'stars', text:'The workspace step asks for a team name before the user has seen any value, so it reads as admin work. Moving it after the first project is created keeps the flow short, and the name can default to the email domain until they change it.' },
  search: { icon:'search', items:[
    ['Searched "onboarding drop-off benchmarks"','8 results'],
    ['Searched "workspace setup step patterns"','6 results'],
    ['Read 3 pages','3 sources kept']
  ]},
  coding: { icon:'code', items:[
    ['Edited <code>Onboarding.tsx</code>','+24 −9'],
    ['Edited <code>tokens.css</code>','+6 −2'],
    ['Ran type check','Passed']
  ]}
};
let thTimers = [], thStart = 0, thTick = null;
const later = (fn, ms) => thTimers.push(setTimeout(fn, ms));
function clearTh(){ thTimers.forEach(clearTimeout); thTimers = []; clearInterval(thTick); }
function markDone(row){
  if (!row || !row.classList.contains('run')) return;
  row.classList.remove('run'); row.classList.add('done');
  const st = row.querySelector('.st'); st.innerHTML = ic('check', 'sm icon-in');
  ambient('c2', 'pop');
}
function finishTh(){
  clearInterval(thTick);
  const s = Math.max(1, Math.round((performance.now() - thStart) / 1000));
  thTitle.classList.remove('shimmer'); swapText(thTitle, 'Reasoned for ' + s + 's'); thTime.textContent = '';
  ambient('c2', 'done');
}
function runThink(v){
  clearTh(); const d = thinkData[v];
  thIcon.textContent = d.icon; thTrace.innerHTML = '';
  thTitle.classList.add('shimmer'); thTitle.textContent = 'Reasoning';
  thStart = performance.now(); thTime.textContent = '0s';
  thTick = setInterval(() => { thTime.textContent = Math.floor((performance.now() - thStart) / 1000) + 's'; }, 250);
  if (d.text){
    const wrap = document.createElement('div');
    wrap.innerHTML = '<div class="uf"><div class="reason">' + d.text.split(' ').map(w => `<span class="w">${w}</span>`).join(' ') + '</div></div>';
    thTrace.appendChild(wrap); unfoldIn(wrap);
    const ws = $$('.w', wrap); let i = 0;
    const step = () => { if (i < ws.length){ ws[i++].classList.add('in'); if (i % 3 === 0) ambient('c2', 'stream'); later(step, reduce ? 0 : 45); } else later(finishTh, 400); };
    later(step, 500);
    return;
  }
  d.items.forEach((it, i) => later(() => {
    markDone(thTrace.lastElementChild && thTrace.lastElementChild.querySelector('.trace-item'));
    const wrap = document.createElement('div');
    wrap.innerHTML = `<div class="uf"><div class="trace-item run"><span class="st"><i class="spin"></i></span><span>${it[0]}<span class="sub">${it[1]}</span></span></div></div>`;
    thTrace.appendChild(wrap); unfoldIn(wrap);
  }, 300 + i * 1200));
  later(() => { markDone(thTrace.lastElementChild && thTrace.lastElementChild.querySelector('.trace-item')); finishTh(); }, 300 + d.items.length * 1200);
}
function setOpen(open){
  thHead.setAttribute('aria-expanded', open ? 'true' : 'false');
  thFold.classList.toggle('open', open);
}
thHead.addEventListener('click', () => {
  const open = thHead.getAttribute('aria-expanded') !== 'true';
  setOpen(open); Sound.play(open ? 'open' : 'close');
});
tabHandlers.think = v => {
  if (thFold.classList.contains('open') && thTrace.children.length){
    setOpen(false); clearTh();
    setTimeout(() => { setOpen(true); runThink(v); }, 450);
  } else { setOpen(true); runThink(v); }
};
runThink('steps');
